            "svg": "<svg viewBox=\"0 0 1100 1100\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"65\" font-size=\"34\" fill=\"#ffd700\" font-weight=\"bold\" text-anchor=\"middle\">Quiz: What Is Authenticity?</text><rect x=\"150\" y=\"220\" width=\"800\" height=\"200\" rx=\"18\" fill=\"rgba(139,92,246,0.12)\" stroke=\"#8b5cf6\" stroke-width=\"3\"/><text x=\"550\" y=\"280\" font-size=\"20\" fill=\"#fff\" text-anchor=\"middle\">Escape? Defiance? Or something</text><text x=\"550\" y=\"320\" font-size=\"20\" fill=\"#fff\" text-anchor=\"middle\">else entirely?</text><rect x=\"200\" y=\"500\" width=\"700\" height=\"220\" rx=\"18\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"3\"/><text x=\"550\" y=\"560\" font-size=\"19\" fill=\"#10b981\" font-weight=\"bold\" text-anchor=\"middle\">Resolutely owning</text><text x=\"550\" y=\"610\" font-size=\"18\" fill=\"#fff\" text-anchor=\"middle\">your thrown situation and</text><text x=\"550\" y=\"645\" font-size=\"18\" fill=\"#fff\" text-anchor=\"middle\">finite possibilities</text></svg>",
